<?php
declare(strict_types=1);
use PHPUnit\Framework\TestCase;
use DigiForgePrintifyConnector\Preparation\{WebhookReconciler,WebhookContract,OrderReadModel,PreparationService};
require_once __DIR__.'/../fixtures/printify-connector/stage34/companion-test-bootstrap.php';
final class PrintifyCompanionWebhookReconciliationTest extends TestCase {
 private function fixture():array{return (require __DIR__.'/../fixtures/printify-connector/batch4/fixture.php')();}
 public function testExactOrderReadbackProducesReviewEvidenceOnly():void{[$s,,,,$o,$l,$event,$secret]=$this->fixture();$raw=json_encode($event);$verified=WebhookContract::verify($s,$raw,'sha256='.hash_hmac('sha256',$raw,$secret),$secret,time());$model=OrderReadModel::fromProvider($s,$o,$l,str_repeat('a',64));$r=WebhookReconciler::order($verified,$model,time());self::assertSame('ORDER_READBACK_MATCHED_REVIEW_REQUIRED',$r['state']);self::assertFalse($r['business_transition_authorized']);self::assertTrue($r['core_receipt_verification_required']);}
 public function testOldReadbackAndOutOfOrderEventCannotApplyState():void{[$s,,,,$o,$l,$event,$secret]=$this->fixture();$raw=json_encode($event);$v=WebhookContract::verify($s,$raw,'sha256='.hash_hmac('sha256',$raw,$secret),$secret,time());$m=OrderReadModel::fromProvider($s,$o,$l,str_repeat('a',64));self::assertSame('AUTHORITATIVE_READBACK_REQUIRED',WebhookReconciler::order($v,$m,$v['created_at']-1)['state']);self::assertSame('OUT_OF_ORDER_REVIEW_REQUIRED',WebhookReconciler::order($v,$m,time(),$v['created_at'])['state']);}
 public function testWrongOrderCannotBeMatched():void{[$s,,,,$o,$l,$event,$secret]=$this->fixture();$raw=json_encode($event);$v=WebhookContract::verify($s,$raw,'sha256='.hash_hmac('sha256',$raw,$secret),$secret,time());$o['id']='other_order';$m=OrderReadModel::fromProvider($s,$o,$l,str_repeat('a',64));$this->expectException(InvalidArgumentException::class);WebhookReconciler::order($v,$m,time());}
 public function testExactProductPublishReadbackRemainsPending():void{[$s,$in,$e,$ctx,,,$event,$secret]=$this->fixture();$event['type']='product:publish:started';$event['resource']['type']='product';$event['resource']['id']=$in['product_id'];$raw=json_encode($event);$v=WebhookContract::verify($s,$raw,'sha256='.hash_hmac('sha256',$raw,$secret),$secret,time());$i=(new PreparationService())->publish($s,$in,$e,$ctx);$r=WebhookReconciler::product($v,$i,['id'=>$in['product_id'],'shop_id'=>(int)$s->providerShopId,'is_locked'=>true],time());self::assertSame('PUBLISH_PENDING',$r['state']);self::assertFalse($r['business_transition_authorized']);}
 public function testTamperedEventEvidenceRejected():void{[$s,,,,$o,$l,$event,$secret]=$this->fixture();$raw=json_encode($event);$v=WebhookContract::verify($s,$raw,'sha256='.hash_hmac('sha256',$raw,$secret),$secret,time());$v['resource_id']='altered';$this->expectException(InvalidArgumentException::class);WebhookReconciler::order($v,OrderReadModel::fromProvider($s,$o,$l,str_repeat('a',64)),time());}
}
